-- ---------- Questions + rubrics ----------
-- 1..5: cau hoi goc (S1, S2); 6..22: them moi
INSERT INTO questions (id, exam_session_id, order_no, content) VALUES
  ('44444444-0000-0000-0000-000000000001', '33333333-0000-0000-0000-000000000001', 1,
   'So sánh kiến trúc modular monolith và microservices. Khi nào nên chọn modular monolith?'),
  ('44444444-0000-0000-0000-000000000002', '33333333-0000-0000-0000-000000000001', 2,
   'Giải thích nguyên lý Dependency Inversion và cho một ví dụ trong dự án .NET.'),
  ('44444444-0000-0000-0000-000000000003', '33333333-0000-0000-0000-000000000001', 3,
   'Khi nào nên dùng message queue giữa các thành phần của hệ thống?'),
  ('44444444-0000-0000-0000-000000000004', '33333333-0000-0000-0000-000000000002', 1,
   'Trình bày vòng đời của một request trong ASP.NET Core middleware pipeline.'),
  ('44444444-0000-0000-0000-000000000005', '33333333-0000-0000-0000-000000000002', 2,
   'Phân biệt AddScoped, AddTransient và AddSingleton.'),
  ('44444444-0000-0000-0000-000000000006', '33333333-0000-0000-0000-000000000002', 3,
   'Entity Framework Core quản lý thay đổi schema bằng migration như thế nào? Khi nào nên dùng raw SQL?'),
  ('44444444-0000-0000-0000-000000000007', '33333333-0000-0000-0000-000000000002', 4,
   'Trình bày cách cấu hình xác thực JWT trong ASP.NET Core Web API.'),
  ('44444444-0000-0000-0000-000000000008', '33333333-0000-0000-0000-000000000003', 1,
   'Phân biệt kiến trúc phân lớp (layered) và Clean Architecture.'),
  ('44444444-0000-0000-0000-000000000009', '33333333-0000-0000-0000-000000000003', 2,
   'Giải thích pattern Repository và Unit of Work. Có nên dùng cùng EF Core không?'),
  ('44444444-0000-0000-0000-000000000010', '33333333-0000-0000-0000-000000000003', 3,
   'Thế nào là coupling và cohesion? Cho ví dụ thiết kế có cohesion cao.'),
  ('44444444-0000-0000-0000-000000000011', '33333333-0000-0000-0000-000000000003', 4,
   'Khi nào nên dùng pattern Strategy? Cho một ví dụ.'),
  ('44444444-0000-0000-0000-000000000012', '33333333-0000-0000-0000-000000000004', 1,
   'Trình bày các dạng chuẩn 1NF, 2NF, 3NF và cho ví dụ vi phạm 2NF.'),
  ('44444444-0000-0000-0000-000000000013', '33333333-0000-0000-0000-000000000004', 2,
   'Phân biệt INNER JOIN và LEFT JOIN, cho ví dụ khi nào dùng LEFT JOIN.'),
  ('44444444-0000-0000-0000-000000000014', '33333333-0000-0000-0000-000000000004', 3,
   'Index là gì? Khi nào index làm chậm hệ thống?'),
  ('44444444-0000-0000-0000-000000000015', '33333333-0000-0000-0000-000000000004', 4,
   'Giải thích các tính chất ACID của transaction.'),
  ('44444444-0000-0000-0000-000000000016', '33333333-0000-0000-0000-000000000005', 1,
   'Phân biệt kiểm thử hộp đen và kiểm thử hộp trắng.'),
  ('44444444-0000-0000-0000-000000000017', '33333333-0000-0000-0000-000000000005', 2,
   'Trình bày kỹ thuật phân vùng tương đương và phân tích giá trị biên, cho ví dụ.'),
  ('44444444-0000-0000-0000-000000000018', '33333333-0000-0000-0000-000000000005', 3,
   'Unit test khác integration test thế nào? Vì sao cần mock?'),
  ('44444444-0000-0000-0000-000000000019', '33333333-0000-0000-0000-000000000005', 4,
   'Một bug report tốt cần có những thông tin gì?'),
  ('44444444-0000-0000-0000-000000000020', '33333333-0000-0000-0000-000000000006', 1,
   'Middleware trong ASP.NET Core là gì? Mô tả một middleware ghi log thời gian xử lý request.'),
  ('44444444-0000-0000-0000-000000000021', '33333333-0000-0000-0000-000000000006', 2,
   'So sánh async/await với việc tự tạo Thread thủ công.'),
  ('44444444-0000-0000-0000-000000000022', '33333333-0000-0000-0000-000000000006', 3,
   'Giải thích cơ chế model binding và validation trong ASP.NET Core.');

INSERT INTO rubrics (question_id, criteria, max_score) VALUES
  ('44444444-0000-0000-0000-000000000001', 'Nêu đúng khác biệt về triển khai và ranh giới module (4đ); nêu được trade-off (3đ); điều kiện chọn modular monolith hợp lý (3đ).', 10),
  ('44444444-0000-0000-0000-000000000002', 'Định nghĩa đúng DIP (4đ); ví dụ interface + DI container (4đ); nêu lợi ích khi test (2đ).', 10),
  ('44444444-0000-0000-0000-000000000003', 'Nêu được xử lý bất đồng bộ / tách phụ thuộc (5đ); ví dụ tình huống cụ thể (3đ); nhắc đến nhược điểm (2đ).', 10),
  ('44444444-0000-0000-0000-000000000004', 'Thứ tự middleware (5đ); vai trò next() và short-circuit (5đ).', 10),
  ('44444444-0000-0000-0000-000000000005', 'Phân biệt đúng 3 lifetime (6đ); ví dụ dùng sai gây lỗi (4đ).', 10),
  ('44444444-0000-0000-0000-000000000006', 'Quy trình add/update migration (5đ); trường hợp nên dùng raw SQL và rủi ro SQL injection (5đ).', 10),
  ('44444444-0000-0000-0000-000000000007', 'AddAuthentication/AddJwtBearer và tham số validate (5đ); phân quyền theo role (3đ); bảo vệ signing key (2đ).', 10),
  ('44444444-0000-0000-0000-000000000008', 'Mô tả đúng các lớp và chiều phụ thuộc (4đ); điểm khác về hướng phụ thuộc vào domain (4đ); ví dụ (2đ).', 10),
  ('44444444-0000-0000-0000-000000000009', 'Định nghĩa Repository (3đ); định nghĩa Unit of Work (3đ); nhận xét DbContext đã là UoW/Repository và khi nào vẫn nên bọc (4đ).', 10),
  ('44444444-0000-0000-0000-000000000010', 'Định nghĩa coupling (3đ); định nghĩa cohesion (3đ); ví dụ đúng (4đ).', 10),
  ('44444444-0000-0000-0000-000000000011', 'Mục đích của Strategy (4đ); cấu trúc interface + các implementation (3đ); ví dụ phù hợp (3đ).', 10),
  ('44444444-0000-0000-0000-000000000012', 'Định nghĩa đúng 1NF, 2NF, 3NF (6đ); ví dụ vi phạm 2NF hợp lý (4đ).', 10),
  ('44444444-0000-0000-0000-000000000013', 'Kết quả INNER JOIN (4đ); kết quả LEFT JOIN với NULL (3đ); ví dụ đúng (3đ).', 10),
  ('44444444-0000-0000-0000-000000000014', 'Định nghĩa và cấu trúc B-tree (4đ); lợi ích khi truy vấn (3đ); chi phí khi ghi và chiếm dung lượng (3đ).', 10),
  ('44444444-0000-0000-0000-000000000015', 'Atomicity (2.5đ); Consistency (2.5đ); Isolation (2.5đ); Durability (2.5đ).', 10),
  ('44444444-0000-0000-0000-000000000016', 'Hộp đen dựa trên đặc tả (4đ); hộp trắng dựa trên mã nguồn (4đ); ví dụ kỹ thuật mỗi loại (2đ).', 10),
  ('44444444-0000-0000-0000-000000000017', 'Phân vùng tương đương (4đ); giá trị biên (4đ); ví dụ đúng (2đ).', 10),
  ('44444444-0000-0000-0000-000000000018', 'Phạm vi unit test (3đ); phạm vi integration test (3đ); mục đích mock (4đ).', 10),
  ('44444444-0000-0000-0000-000000000019', 'Tiêu đề, bước tái hiện, kết quả mong đợi và thực tế (3đ); môi trường, mức độ, bằng chứng (2đ).', 5),
  ('44444444-0000-0000-0000-000000000020', 'Khái niệm pipeline và next() (5đ); ví dụ middleware đo thời gian (5đ).', 10),
  ('44444444-0000-0000-0000-000000000021', 'async/await không chặn thread khi I/O (5đ); chi phí và quản lý Thread (5đ).', 10),
  ('44444444-0000-0000-0000-000000000022', 'Nguồn binding: route, query, body (5đ); DataAnnotations và ModelState / [ApiController] (5đ).', 10);

