-- ---------- Interview turns (tap cac turn = transcript; answer NULL = het gio chua tra loi) ----------
INSERT INTO interview_turns (question_response_id, turn_no, type, question_text, answer_transcript, audio_url, asked_at, answered_at) VALUES
  -- Chau - Q1 (co 1 cau hoi xoay)
  ('77777777-0000-0000-0000-000000000001', 1, 'Main',
   'So sánh kiến trúc modular monolith và microservices. Khi nào nên chọn modular monolith?',
   'Modular monolith triển khai một khối nhưng chia module rõ ràng, còn microservices tách thành nhiều service riêng. Nhóm nhỏ thì nên chọn modular monolith.',
   'audio/66666666-0001/q1-t1.webm', '2026-10-01 09:00:30+07', '2026-10-01 09:02:00+07'),
  ('77777777-0000-0000-0000-000000000001', 2, 'FollowUp',
   'Em có thể nêu một trade-off cụ thể khi chọn modular monolith không?',
   'Dễ triển khai và debug hơn, nhưng không scale riêng từng module được.',
   'audio/66666666-0001/q1-t2.webm', '2026-10-01 09:02:10+07', '2026-10-01 09:03:00+07'),
  -- Chau - Q2
  ('77777777-0000-0000-0000-000000000002', 1, 'Main',
   'Giải thích nguyên lý Dependency Inversion và cho một ví dụ trong dự án .NET.',
   'Module cấp cao không phụ thuộc module cấp thấp mà cả hai phụ thuộc abstraction. Ví dụ service nhận IRepository qua constructor và đăng ký trong DI container, khi test thì mock được.',
   'audio/66666666-0001/q2-t1.webm', '2026-10-01 09:03:30+07', '2026-10-01 09:05:20+07'),
  -- Chau - Q3
  ('77777777-0000-0000-0000-000000000003', 1, 'Main',
   'Khi nào nên dùng message queue giữa các thành phần của hệ thống?',
   'Khi cần xử lý bất đồng bộ, ví dụ gửi email sau khi đặt hàng, để không bắt người dùng chờ.',
   'audio/66666666-0001/q3-t1.webm', '2026-10-01 09:06:00+07', '2026-10-01 09:07:30+07'),
  -- Dung - Q1
  ('77777777-0000-0000-0000-000000000004', 1, 'Main',
   'So sánh kiến trúc modular monolith và microservices. Khi nào nên chọn modular monolith?',
   'Microservices tốt hơn vì scale được, monolith là kiến trúc cũ.',
   'audio/66666666-0002/q1-t1.webm', '2026-10-01 10:00:30+07', '2026-10-01 10:01:40+07'),
  -- Dung - Q2 (2 cau hoi xoay, cau cuoi het gio chua tra loi)
  ('77777777-0000-0000-0000-000000000005', 1, 'Main',
   'Giải thích nguyên lý Dependency Inversion và cho một ví dụ trong dự án .NET.',
   'Là dùng dependency injection.',
   'audio/66666666-0002/q2-t1.webm', '2026-10-01 10:02:00+07', '2026-10-01 10:02:40+07'),
  ('77777777-0000-0000-0000-000000000005', 2, 'FollowUp',
   'Dependency injection và Dependency Inversion khác nhau thế nào?',
   'Injection là cách đưa đối tượng vào, còn inversion thì em chưa rõ lắm.',
