  ('77777777-0000-0000-0000-000000000001', 7.5, 'Phân biệt đúng hai kiến trúc và nêu được trade-off; điều kiện chọn còn chung chung.', '2026-10-01 09:12:30+07'),
  ('77777777-0000-0000-0000-000000000002', 9.0, 'Định nghĩa chính xác, ví dụ phù hợp và có nhắc lợi ích khi test.',                  '2026-10-01 09:12:30+07'),
  ('77777777-0000-0000-0000-000000000003', 6.0, 'Nêu đúng xử lý bất đồng bộ và có ví dụ; chưa đề cập nhược điểm.',                 '2026-10-01 09:12:30+07'),
  ('77777777-0000-0000-0000-000000000004', 2.0, 'Nhận định thiếu chính xác, chưa nêu khác biệt và trade-off.',                     '2026-10-01 10:10:30+07'),
  ('77777777-0000-0000-0000-000000000005', 3.0, 'Nhầm lẫn giữa Dependency Injection và Dependency Inversion; không trả lời câu hỏi xoáy cuối.', '2026-10-01 10:10:30+07'),
  ('77777777-0000-0000-0000-000000000006', 4.5, 'Có ví dụ sau khi được gợi ý nhưng chưa giải thích lý do dùng queue.',             '2026-10-01 10:10:30+07'),
  ('77777777-0000-0000-0000-000000000007', 6, 'Nêu được một phần ý chính; sau câu hỏi xoáy vẫn còn thiếu trade-off và điều kiện lựa chọn cụ thể.', timestamptz '2026-10-02 08:00+07' + interval '203 seconds'),
  ('77777777-0000-0000-0000-000000000008', 7, 'Nêu được một phần ý chính; sau câu hỏi xoáy vẫn còn thiếu phân biệt nguyên lý với kỹ thuật DI và lợi ích khi test.', timestamptz '2026-10-02 08:00+07' + interval '401 seconds'),
  ('77777777-0000-0000-0000-000000000009', 9, 'Nêu đủ các ý chính theo rubric, giải thích rõ và có ví dụ phù hợp.', timestamptz '2026-10-02 08:00+07' + interval '524 seconds'),
